import os
import hashlib
import hmac
import secrets
import sqlite3
import re
from pathlib import Path, PurePosixPath
from urllib.parse import unquote
from functools import wraps
from flask import Flask, request, jsonify, g, session
import bcrypt

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET_KEY', secrets.token_hex(32))

DOCUMENT_ROOT = Path('/srv/documents').resolve()
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.md', '.docx', '.png', '.jpg'}
MAX_PATH_LENGTH = 256
RATE_LIMIT_WINDOW = 60
RATE_LIMIT_MAX = 100

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(os.environ.get('DB_PATH', '/var/lib/app/users.db'))
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return jsonify({'error': 'Authentication required'}), 401
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
        if user is None:
            session.clear()
            return jsonify({'error': 'Invalid session'}), 401
        g.current_user = user
        return f(*args, **kwargs)
    return decorated

def check_rate_limit(user_id):
    """Simple in-memory rate limiting per user"""
    import time
    if not hasattr(app, '_rate_limits'):
        app._rate_limits = {}
    now = time.time()
    key = f"{user_id}"
    if key not in app._rate_limits:
        app._rate_limits[key] = []
    # Clean old entries
    app._rate_limits[key] = [t for t in app._rate_limits[key] if now - t < RATE_LIMIT_WINDOW]
    if len(app._rate_limits[key]) >= RATE_LIMIT_MAX:
        return False
    app._rate_limits[key].append(now)
    return True

def get_user_acl(user_id):
    """Get list of directory prefixes user is allowed to access"""
    db = get_db()
    rows = db.execute('SELECT allowed_path FROM user_acls WHERE user_id = ?', (user_id,)).fetchall()
    return [row['allowed_path'] for row in rows]

def is_path_allowed(request_path, allowed_prefixes):
    """Check if the requested path falls under any allowed prefix.
    Uses the raw request path for consistent ACL matching."""
    # Normalize the path for comparison
    normalized = PurePosixPath(request_path)
    path_str = str(normalized)

    # Security: reject obvious traversal attempts in the raw path
    if '..' in path_str.split('/'):
        return False

    # Check against ACL prefixes
    for prefix in allowed_prefixes:
        if path_str.startswith(prefix):
            return True
    return False

def resolve_document_path(request_path):
    """Resolve the actual filesystem path for a document request.
    Decodes URL-encoded characters for filesystem access."""
    # Decode percent-encoded characters for actual file access
    decoded_path = unquote(request_path)

    # Remove leading slash for path joining
    clean = decoded_path.lstrip('/')

    # Construct full path
    full_path = (DOCUMENT_ROOT / clean).resolve()

    # Verify it's still within document root
    if not str(full_path).startswith(str(DOCUMENT_ROOT)):
        return None

    # Check extension
    if full_path.suffix.lower() not in ALLOWED_EXTENSIONS:
        return None

    return full_path

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password'].encode('utf-8')

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    if user is None:
        # Constant-time comparison to prevent user enumeration
        bcrypt.checkpw(password, b'$2b$12$' + b'0' * 53)
        return jsonify({'error': 'Invalid credentials'}), 401

    if bcrypt.checkpw(password, user['password_hash'].encode('utf-8')):
        session['user_id'] = user['id']
        session.permanent = True
        return jsonify({'message': 'Login successful', 'user': user['username']})

    return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/logout', methods=['POST'])
def logout():
    session.clear()
    return jsonify({'message': 'Logged out'})

@app.route('/documents/<path:filepath>', methods=['GET'])
@require_auth
def get_document(filepath):
    user_id = g.current_user['id']

    # Rate limiting
    if not check_rate_limit(user_id):
        return jsonify({'error': 'Rate limit exceeded'}), 429

    # Path length check
    if len(filepath) > MAX_PATH_LENGTH:
        return jsonify({'error': 'Path too long'}), 400

    # Get user's allowed paths from ACL
    allowed_prefixes = get_user_acl(user_id)
    if not allowed_prefixes:
        return jsonify({'error': 'No access configured'}), 403

    # Authorization check: verify user can access this path
    # Uses the request path as-is for ACL matching
    if not is_path_allowed('/' + filepath, allowed_prefixes):
        return jsonify({'error': 'Access denied'}), 403

    # Resolve actual filesystem path (decodes URL encoding)
    resolved = resolve_document_path(filepath)
    if resolved is None:
        return jsonify({'error': 'Invalid path'}), 400

    if not resolved.exists():
        return jsonify({'error': 'Not found'}), 404

    # Read and return file content
    try:
        content = resolved.read_bytes()
        return content, 200, {'Content-Type': 'application/octet-stream',
                              'X-Content-Type-Options': 'nosniff'}
    except PermissionError:
        return jsonify({'error': 'Permission denied'}), 403

@app.route('/documents', methods=['GET'])
@require_auth
def list_documents():
    user_id = g.current_user['id']
    allowed_prefixes = get_user_acl(user_id)

    documents = []
    for prefix in allowed_prefixes:
        prefix_path = DOCUMENT_ROOT / prefix.lstrip('/')
        if prefix_path.exists() and prefix_path.is_dir():
            for f in prefix_path.rglob('*'):
                if f.is_file() and f.suffix.lower() in ALLOWED_EXTENSIONS:
                    rel = f.relative_to(DOCUMENT_ROOT)
                    documents.append(str(rel))

    return jsonify({'documents': documents})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
